/// <summary>
/// CB202_SalesQuotaMinMax
/// </summary>
class METAgreementLineSearchParameters
{
    private ItemId           itemId;
    private SalesReceiptDate receiptDate;
    private CustAccount      custAccount;
    private InventDim        inventDim;
    private SalesUnit        salesUnit;

}

Method.Source:
/// <summary>
/// New method
/// </summary>
/// <param name = "_itemId">Item number</param>
/// <param name = "_receiptDate">Receipt date</param>
/// <param name = "_custAccount">Customer account</param>
/// <param name = "_salesUnit">SO line UOM</param>
/// <param name = "_inventDim">Sales order line inventory dimension</param>
protected void new(ItemId           _itemId,
                   SalesReceiptDate _receiptDate,
                   CustAccount      _custAccount,
                   SalesUnit        _salesUnit,
                   InventDim        _inventDim)
{
    itemId      = _itemId;
    receiptDate = _receiptDate;
    custAccount = _custAccount;
    salesUnit   = _salesUnit;
    inventDim   = _inventDim;
}

/// <summary>
/// Construct method
/// </summary>
/// <param name = "_itemId">Item number</param>
/// <param name = "_receiptDate">Receipt date</param>
/// <param name = "_custAccount">Customer account</param>
/// <param name = "_salesUnit">SO line UOM</param>
/// <param name = "_inventDim">Sales order line inventory dimension</param>
/// <returns>Instance of <c>METSalesItemSubstituteSearchParameters</c></returns>
public static METAgreementLineSearchParameters construct(ItemId             _itemId,
                                                         SalesReceiptDate   _receiptDate,
                                                         CustAccount        _custAccount,
                                                         SalesUnit          _salesUnit,
                                                         InventDim          _inventDim)
{
    return new METAgreementLineSearchParameters(_itemId, _receiptDate, _custAccount, _salesUnit, _inventDim);
}

/// <summary>
/// Get method for item number
/// </summary>
/// <returns>Item number</returns>
final public ItemId getItemId()
{
    return itemId;
}

/// <summary>
/// Get method for receipt date
/// </summary>
/// <returns>Receipt date</returns>
final public SalesReceiptDate getReceiptDate()
{
    return receiptDate;
}

/// <summary>
/// Get method for customer account
/// </summary>
/// <returns>Customer account</returns>
final public CustAccount getCustAccount()
{
    return custAccount;
}

/// <summary>
/// Get method for sales unit
/// </summary>
/// <returns>Sales unit</returns>
final public SalesUnit getSalesUnit()
{
    return salesUnit;
}

/// <summary>
/// Get method for inventory dimensions
/// </summary>
/// <returns>Inventory dimensions</returns>
final public InventDim getInventDim()
{
    return inventDim;
}
